var i=`0584-turkmen-palaw`;var t=`world-0584`;var r=`TM`;var a=`central-asia`;var o=4;var s=108;var l={en:`Turkmen Palaw`,ua:`Туркменський палав`};var u={en:`A traditional dish from Turkmenistan, centered on lamb, yellow onion, carrot, basmati rice. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туркменістан. Основні складники: ягнятина, жовта цибуля, морква, рис басматі. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 14 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 14 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:14,i:[[`lamb`,700,`g`],[`yellow-onion`,250,`g`],[`sunflower-oil`,75,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 55 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 55 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:55,i:[[`carrot`,580,`g`],[`cumin-seeds`,5,`g`],[`water`,680,`ml`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 27 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 27 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:27,i:[[`basmati-rice`,470,`g`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 12 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 12 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:12,i:[]}];var m={slug:i,id:t,country:`TM`,region:a,servings:4,minutes:108,title:l,text:u,steps:d};export{r as country,m as default,t as id,s as minutes,a as region,o as servings,i as slug,d as steps,u as text,l as title};